{
  "headline": "Succinylcholine chloride is not on FDA's shortage list; Fresenius Kabi USA, LLC posted a discontinuation on 2026-07-23 and a registered plant for Eugia Pharma Specialities Limited was classified OAI on 2026-02-06",
  "headline_cites": ["D3", "E13", "E12"],
  "sentences": [
    {
      "text": "FDA's drug shortage list does not include succinylcholine chloride as of 2026-10-21.",
      "cites": ["D3"]
    },
    {
      "text": "Fresenius Kabi USA, LLC posted a discontinuation of succinylcholine chloride injection on 2026-07-23.",
      "cites": ["E13"]
    },
    {
      "text": "A registered plant for Eugia Pharma Specialities Limited (FEI 3008461619) was classified OAI after an inspection ending 2026-02-06.",
      "cites": ["E12", "E10"]
    },
    {
      "text": "The same plant received a Warning Letter on 2024-08-15.",
      "cites": ["E11"]
    },
    {
      "text": "Corvale East holds 75 vials (20.5 days on hand) and Corvale General holds 106 vials (26.1 days on hand) of the 20 mg/mL, 10 mL presentation.",
      "cites": ["D1", "D2"]
    },
    {
      "text": "The rule‑based best option is to buy from BE Pharmaceuticals Inc., which is not on FDA's shortage list today and whose label names no plant we could place.",
      "cites": ["D4"]
    }
  ]
}
